/// <summary>
///    AVA <c>initValue</c> method.
/// </summary>
/// <param name="_salesType">
///    <c>SalesType</c> as type
/// </param>
public void initValue(SalesType _salesType)
{
    next initValue(_salesType);

    this.avaInitValue();
}

/// <summary>
///    AVA <c>avaInitValue</c> method.
/// </summary>
public void avaInitValue()
{
    this.AVACBSSpecialPrice = this.salesTable().KCS_BOSSpecialPrice;
    this.DEL_KCS_CustShipDateReq = this.salesTable().DEL_KCS_CustShipDateReq;
    // this.MatchingAgreementLine = !AVASalesParameters::find().PriceSearch;
}

/// <summary>
/// returns the phsyically reserved qty from invent trans for this salesLine
/// </summary>
/// <returns>AVAQtyReserved</returns>
public AVAQtyReserved avaGetInventTransQtyReserved()
{
    InventTrans         inventTrans;
    InventTransOrigin   inventTransOrig;

    select sum(Qty) from inventTrans
         where inventTrans.StatusReceipt == StatusReceipt::None
               && inventTrans.StatusIssue == StatusIssue::ReservPhysical
            exists join inventTransOrig
                where inventTransOrig.RecId == inventTrans.InventTransOrigin
                     && inventTransOrig.InventTransId == this.InventTransId;

    return  inventTrans.Qty * -1;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_calcSalesPrice">_calcSalesPrice</param>
/// <param name = "_calcPriceDiscount">_calcPriceDiscount</param>
/// <param name = "_netPG1Price">_netPG1Price</param>
/// <param name = "_netPG2Price">_netPG2Price</param>
/// <param name = "_calcMasterPrice">_calcMasterPrice</param>
public void AVApriceCalculation(boolean    _calcSalesPrice = true,
                                boolean    _calcPriceDiscount = true,
                                boolean    _netPG1Price = true,
                                boolean    _netPG2Price = true,
                                boolean    _calcMasterPrice = true)
{
    SalesLine               salesLine = this;
    SalesTable              salesTable = salesLine.salesTable();
    PriceDiscTable          priceDiscTable;

    SalesPrice              lpSalesPrice;
    SalesPrice              lpPriceDiscount;
    SalesPrice              lpPriceDiscounted;
    SalesPrice              AVANetPG1Price;
    SalesPrice              AVANetPG2Price;
    SalesPrice              bestPrice;
    SalesPrice              quotPrice;
    SalesQuotationLine      salesQuotationline;

    if (_calcSalesPrice)
    {
        priceDiscTable =  AVAPriceDiscGroupSearch::findPriceDisc(PriceType::PriceSales,
                                                                  salesTable.PriceGroupId,
                                                                  salesTable.KCS_ChainLineDiscCode,
                                                                  this.itemId,
                                                                  this.KCS_PriceDate != dateNull() ? this.KCS_PriceDate : DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),
                                                                  Ledger::accountingCurrency(CompanyInfo::current()));

        //lpSalesPrice = salesTable.CurrencyCode == priceDiscTable.Currency ? priceDiscTable.Amount : CurrencyExchangeHelper::amount(priceDiscTable.Amount,priceDiscTable.Currency);
        lpSalesPrice = priceDiscTable.Amount;

    }
    if (_calcPriceDiscount)
    {
        lpPriceDiscount = AVAPriceDiscGroupSearch::findPriceDisc(PriceType::LineDiscSales,
                                                                  salesTable.LineDisc,
                                                                  salesTable.KCS_ChainLineDiscCode,
                                                                  this.itemId,
                                                                  this.KCS_PriceDate != dateNull() ? this.KCS_PriceDate : DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),
                                                                  Ledger::accountingCurrency(CompanyInfo::current())).Percent1;
    }

    lpPriceDiscounted = lpSalesPrice * (1 -   lpPriceDiscount/100);
    if(_netPG1Price)
    {
        priceDiscTable =   AVAPriceDiscGroupSearch::findPriceDisc(PriceType::PriceSales,
                                                                  salesTable.AVANetPG1,
                                                                  salesTable.KCS_ChainLineDiscCode,
                                                                  this.itemId,
                                                                  this.KCS_PriceDate != dateNull() ? this.KCS_PriceDate : DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),
                                                                  Ledger::accountingCurrency(CompanyInfo::current()));

        //AVANetPG1Price = salesTable.CurrencyCode == priceDiscTable.Currency ? priceDiscTable.Amount :
        //                                                            CurrencyExchangeHelper::amount(priceDiscTable.Amount,priceDiscTable.Currency);
        AVANetPG1Price = priceDiscTable.Amount;
    }
    if(_netPG2Price)
    {
        priceDiscTable = AVAPriceDiscGroupSearch::findPriceDisc(PriceType::PriceSales,
                                                                  salesTable.AVANetPG2,
                                                                  '',
                                                                  this.itemId,
                                                                  this.KCS_PriceDate != dateNull() ? this.KCS_PriceDate : DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),
                                                                  Ledger::accountingCurrency(CompanyInfo::current()));

        //AVANetPG2Price = salesTable.CurrencyCode == priceDiscTable.Currency ? priceDiscTable.Amount :
        //                                                            CurrencyExchangeHelper::amount(priceDiscTable.Amount,priceDiscTable.Currency);
        AVANetPG2Price =  priceDiscTable.Amount;
    }

    bestPrice = lpPriceDiscounted;
    bestPrice = AVANetPG1Price > 0 ? (bestPrice > 0  ? min( bestPrice, AVANetPG1Price) : AVANetPG1Price) :   bestPrice;
    bestPrice = AVANetPG2Price > 0 ? (bestPrice > 0  ? min( bestPrice, AVANetPG2Price) : AVANetPG2Price) :   bestPrice;

    if ( salesLine.AVAQuotationId != '' && salesTable.KCS_NoUseQuotPrice == NoYes::No)
    {
        select firstonly   salesQuotationline
            order by SalesPrice ASC
            where salesQuotationLine.QuotationId == salesLine.AVAQuotationId
            && salesQuotationline.ItemId      == this.ItemId;

        quotPrice = salesQuotationline.SalesPrice;
    }

    bestPrice = (quotPrice > 0 && bestPrice > 0) ? min(bestPrice,quotPrice) : bestPrice > 0 ? bestPrice : quotPrice;
    // this.SalesPrice = bestPrice;

    this.SalesPrice     = bestPrice == lpPriceDiscounted ? lpSalesPrice : bestPrice;
    this.LinePercent    = bestPrice == lpPriceDiscounted ? lpPriceDiscount : 0;
    // this.LineDisc       =  bestPrice == lpPriceDiscounted ?  (lpSalesPrice * lpPriceDiscount)/100 : 0;
}

/// <summary>
/// defined from AVA
/// </summary>
/// <returns>boolean</returns>
protected boolean mustResetPriceAndDiscounts()
{
    boolean ret = next mustResetPriceAndDiscounts();
    ret = AVASalesParameters::find().PriceSearch;
    return ret;
}

/// <summary>
/// Updates the <c>SalesLine</c> based on the given item.
/// </summary>
/// <param name="_inventTable">
///     The <c>InventTable</c> buffer to initialize from.
/// </param>
/// <param name="_resetPrice">
///     A Boolean value indicating whether to reset price.
/// </param>
/// <param name="_matchingAgreement">
/// The record ID of the agreement header that is associated with the sales order. Used for the
/// automatic association with an agreement line.
/// </param>
/// <param name="_performVariantValidation">
///     A Boolean value indicating whether to perform variant validation.
/// </param>
public void initFromInventTable(InventTable                     _inventTable,
                                boolean                         _resetPrice,
                                SalesAgreementHeaderRefRecId    _matchingAgreement,
                                boolean                         _performVariantValidation)
{
    KCS_PriceDate locKCS_PriceDate;

    next initFromInventTable(   _inventTable,
                                _resetPrice,
                                _matchingAgreement,
                                _performVariantValidation   );

    locKCS_PriceDate = this.AVAPriceDate();

    this.AVAPriceSurchargeCode          = _inventTable.avaGetPriceSurchargeCode();

    if(this.AVAPriceSurchargeCode)
    {
        if(this.KCS_PriceDate == dateNull())
        {
            this.AVAPriceSurchargePercentage    = _inventTable.avaGetPriceSurchargePercentage(this.AVAPriceSurchargeCode);
        }
        else
        {
            this.avaSetSurchargeValues();
        }
    }

    this.NDX_PreferenceAuthorized       = _inventTable.NDX_PreferenceAuthorized;
}

/// <summary>
///     AVA <c>avaSetSurchargeValues</c> method.
/// </summary>
public void avaSetSurchargeValues()
{
    if(this.AVAPriceSurchargeCode)
    {
        if(this.KCS_PriceDate == dateNull())
        {
            this.AVAPriceSurchargePercentage    = AVAPriceSurchargeValues::find(this.AVAPriceSurchargeCode).Percentage;
        }
        else
        {
            this.AVAPriceSurchargePercentage    = AVAPriceSurchargeValues::findAtDate(this.AVAPriceSurchargeCode, this.KCS_PriceDate).Percentage;
        }
    }
}

/// <summary>
///     AVA <c>avaPriceDate</c> method.
/// </summary>
/// <returns>
///     <c>KCS_PriceDate</c> as return value
/// </returns>
KCS_PriceDate avaPriceDate()
{
    if (this.KCS_PriceDate)
    {
        return this.KCS_PriceDate;
    }

    if (this.salesTable().KCS_PriceDate)
    {
        return this.salesTable().KCS_PriceDate;
    }

    return DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_salesLine">_salesLine</param>
/// <returns>AVAStockAvailability</returns>
public AVAStockAvailability avaGetStockAvailablityStandard(SalesLine _salesLine = this)
{
    AVAStockAvailability    retVal;

    InventQty               tmpQty;
    InventQty               locInventQtyAvailable;
    InventQty               locInventQtyRemaining;
    InventQty               locInventQtyPicked;
    InventQty               locInventQtyReserved;

    locInventQtyRemaining   = _salesLine.RemainSalesPhysical;
    locInventQtyPicked      = _salesLine.pickedInTotalSalesUnit();
    locInventQtyReserved    = _salesLine.reservedPhysicalInSalesUnit();

    if(this.avaHasShippingAbility())
    {
        if(locInventQtyRemaining - locInventQtyReserved <= 0.0)
        {
            return AVAStockAvailability::Available;
        }
        locInventQtyAvailable   = _salesLine.avaPhysicalAvailForShipping();
        // locInventQtyReserved    = _salesLine.avaPhysicalReservedAbilityForShipping();
        // allready contained in locInventQtyAvailable
        locInventQtyReserved    = 0.0;
        // locInventQtyAvailable already without reserved qty, so tmpQty calculation will be corrected
    }
    else
    {
        locInventQtyAvailable   = _salesLine.avaAvailPhysical();
    }

    tmpQty                  = locInventQtyRemaining - locInventQtyPicked - locInventQtyReserved;

    if(locInventQtyAvailable >= tmpQty)
    {
        retVal = AVAStockAvailability::Available;
    }
    else if(    locInventQtyAvailable > 0
            &&  locInventQtyAvailable < tmpQty  )
    {
        retVal = AVAStockAvailability::PartitialAvailable;
    }
    else if(locInventQtyAvailable <= 0)
    {
        retVal = AVAStockAvailability::NotAvailable;
    }

    return retVal;
}

/// <summary>
///    AVA <c>avaCheckTransferInventSiteAndLocation</c> method.
/// </summary>
/// <param name="_from">
///    <c>InventDim</c> as type
/// </param>
/// <param name="_to">
///    <c>InventDim</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as type
/// </returns>
public boolean avaCheckForTransferInventSiteAndLocation(InventDim _from = this.inventDim(), InventDim _to = this.inventDim())
{
    boolean                 retVal;
    boolean                 locCheckFailed;
    boolean                 locPysicalReservatedFound;
    boolean                 locOpenScanActivityFound;

    SalesLine               locItemSetSalesLineParent;
    SalesLine               locItemSetSalesLineSearch;

    void checkSingleSalesLine(SalesLine _salesLine)
    {
        if(!locPysicalReservatedFound && _salesLine.reservedPhysicalInSalesUnit() > 0)
        {
            locCheckFailed              = checkFailed("@NDX:NXATransferOfSalesLineReservatedNotPossible");
            retVal                      = false;
            locPysicalReservatedFound   = true;
        }
        if(!locOpenScanActivityFound && _salesLine.avaOpenWHSWorkTableExists().RecId)
        {
            locCheckFailed              = checkFailed("@NDX:NXATransferOfSalesLineWithOpenScanActivityNotPossible");
            retVal                      = false;
            locOpenScanActivityFound    = true;
        }
    }

    retVal = true;

    if(     this.AVAItemSetComponent
        ||  (this.AVAItemSet && this.avaIsItemSetExpanded()) )
    {
        if(this.AVAItemSet)
        {
            locItemSetSalesLineParent = this;
        }
        if(this.AVAItemSetComponent && this.AVAItemSetParent)
        {
            locItemSetSalesLineParent = SalesLine::findInventTransId(this.AVAItemSetParent);
        }
        while select locItemSetSalesLineSearch
            where   locItemSetSalesLineSearch.SalesId           == locItemSetSalesLineParent.SalesId
                &&  locItemSetSalesLineSearch.AVAItemSetParent  == locItemSetSalesLineParent.InventTransId
        {
            checkSingleSalesLine(locItemSetSalesLineSearch);
        }
    }
    else
    {
        checkSingleSalesLine(this);
    }

    return retVal;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>AVAStockAvailability</returns>
public AVAStockAvailability avaGetStockAvailablity()
{
    AVAStockAvailability    retVal;

    ProdTable               locProdtable;
    ReqGroup                locReqGroup;

    AVAStockAvailability    retValBundle;
    SalesLine               locItemSetSalesLineParent;
    SalesLine               locItemSetSalesLineSearch;


    retVal = AVAStockAvailability::Unknown;

    locReqGroup = ReqGroup::find(this.inventTable().ReqGroupId);        // Item coverage group /  Artikeldeckungsgruppe

    if (    locReqGroup.CovRule                 == ReqCovType::Req      // Requirement / Einzelbedarf
        &&  locReqGroup.AuthorizationTimeFence  > 0                 )   // Automatic firming time fence (days) / Automatischer Sofortanlagezeitraum (Tage)
    {
        select firstonly locProdtable
        where   locProdtable.InventRefType      == InventRefType::Sales
            &&  locProdtable.InventRefId        == this.SalesId
            &&  locProdtable.InventRefTransId   == this.InventTransId;

        if (locProdtable.prodstatus == prodstatus::StartedUp)
        {
            if (InventTrans::findTransId(locProdtable.InventTransId).StatusReceipt == StatusReceipt::Ordered)
            {
                retVal = AVAStockAvailability::IndividualRequired;
            }
            else
            {
                retVal = AVAStockAvailability::Available;
            }
        }
    }
    else
    {
        if(     this.AVAItemSetComponent
            ||  (this.AVAItemSet && this.avaIsItemSetExpanded()) )
        {
            if(this.AVAItemSet)
            {
                locItemSetSalesLineParent = this;
            }
            if(this.AVAItemSetComponent && this.AVAItemSetParent)
            {
                locItemSetSalesLineParent = SalesLine::findInventTransId(this.AVAItemSetParent);
            }
            while select locItemSetSalesLineSearch
            where   locItemSetSalesLineSearch.SalesId           == locItemSetSalesLineParent.SalesId
                &&  locItemSetSalesLineSearch.AVAItemSetParent  == locItemSetSalesLineParent.InventTransId
            {
                retValBundle = this.avaGetStockAvailablityStandard(locItemSetSalesLineSearch);

                if(retVal == AVAStockAvailability::Unknown)
                {
                    retVal = retValBundle;
                }
                if(     retVal          == AVAStockAvailability::Available
                    &&  (retValBundle   == AVAStockAvailability::PartitialAvailable || retValBundle   == AVAStockAvailability::NotAvailable)  )
                {
                    retVal = retValBundle;
                }
                if(     retVal          == AVAStockAvailability::PartitialAvailable
                    &&  retValBundle    == AVAStockAvailability::NotAvailable       )
                {
                    retVal = retValBundle;
                }
            }
        }
        else  // bundle not exploded or standard sales line
        {
            retVal = this.avaGetStockAvailablityStandard(this);
        }

    }
    if (retVal == AVAStockAvailability::Unknown)  // bundle not exploded or standard sales line
    {
        retVal = this.avaGetStockAvailablityStandard(this);
    }

    if(this.AVAisInCylceCount())
    {
        retVal = AVAStockAvailability::InCycleCount;
    }

    return retVal;
}

/// <summary>
/// N.Freidenberger 27.01.2025
/// </summary>
/// <returns>boolean</returns>
public boolean AVAisInCylceCount()
{
    boolean ret;
    WHSWorkLineCycleCount       whsWorkLineCycleCount;

    select firstonly whsWorkLineCycleCount
        where whsWorkLineCycleCount.ItemId == this.ItemId  
           && whsWorkLineCycleCount.AcceptReject ==   WHSAcceptReject::None;

    if(whsWorkLineCycleCount)
    {
        WHSWorkTable        whsWorkTable = WHSWorkTable::find(whsWorkLineCycleCount.WorkId);        
        InventDim           locInventDim = this.inventDim();
        if (whsWorkTable.InventLocationId == locInventDim.InventLocationId)
        {
            if (!InventSite::find(locInventDim.InventSiteId).AVAShippingAbility)
            {
                ret =true;
            }
            else
            {
                WMSLocation     wmsLocation;
                WHSZone         whsZone;
                WHSZoneGroup    whsZoneGroup;
                select firstonly wmsLocation
                    where wmsLocation.wMSLocationId == locInventDim.wMSLocationId
                        join  whsZone
                            where whsZone.ZoneId ==wmsLocation.ZoneId
                            join whsZoneGroup
                            where whsZoneGroup.ZoneGroupId == whsZone.ZoneGroupId
                               && whsZoneGroup.AVAWHSZoneGroupShipment == NoYes::Yes;

                if(wmsLocation.RecId != 0)
                {
                    ret = true;
                }
            }
        }
    }

    return ret;
}

/// <summary>
///    AVA <c>avaStockAvailabilityIcon</c> method.
/// </summary>
/// <returns>
///     <c>container</c> as type
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display container avaStockAvailabilityIcon()
{
    container               retVal;
    AVAStockAvailability    locAVAStockAvailability;

    ImageReference          locImageReference;

    locAVAStockAvailability = this.avaGetStockAvailablity();

    switch (locAVAStockAvailability)
    {
        case AVAStockAvailability::Unknown:
            retVal = conNull();
            break;

        case AVAStockAvailability::Available:
            locImageReference   = ImageReference::constructForSymbol(ImageReferenceSymbol::GreenSquare);
            break;

        case AVAStockAvailability::PartitialAvailable:
            locImageReference   = ImageReference::constructForSymbol(ImageReferenceSymbol::YellowSquare);
            break;

        case AVAStockAvailability::NotAvailable:
            locImageReference   = ImageReference::constructForSymbol(ImageReferenceSymbol::RedSquare);
            break;

        case AVAStockAvailability::IndividualRequired:
            locImageReference   = ImageReference::constructForSymbol(ImageReferenceSymbol::BlueSquare);
            break;

        case AVAStockAvailability::InCycleCount:
            locImageReference   = ImageReference::constructForSymbol(ImageReferenceSymbol::Warning);
            break;

        default:
            retVal = conNull();
    }

    if(locImageReference)
    {
        retVal = locImageReference.pack();
    }

    return retVal;
}

/// <summary>
///    AVA <c>avaOpenWHSWorkTableExists</c> method.
/// </summary>
/// <returns>
///     <c>WHSWorkTable</c> as type
/// </returns>
public WHSWorkTable avaOpenWHSWorkTableExists()
{
    WHSWorkTable    retVal;

    WHSWorkTable    locWHSWorkTable;
    WHSWorkLine     locWHSWorkLine;

    select firstonly locWHSWorkTable
    where   locWHSWorkTable.WorkTransType   == WHSWorkTransType::Sales
        &&  locWHSWorkTable.WorkStatus      == WHSWorkStatus::Open
        &&  locWHSWorkTable.OrderNum        == this.SalesId
        join locWHSWorkLine
        where   locWHSWorkLine.WorkId       == locWHSWorkTable.WorkId
            &&  locWHSWorkLine.WorkStatus   == WHSWorkStatus::Open
            &&  locWHSWorkLine.ItemId       == this.ItemId;

    retVal = locWHSWorkTable;

    return retVal;
}

/// <summary>
///    AVA <c>avaOpenWHSWorkTableExists</c> method.
/// </summary>
/// <returns>
///     <c>WHSQtyWork</c> as type
/// </returns>
public WHSQtyWork avaOpenWHSWorkTableQty()
{
    WHSQtyWork      retVal;

    WHSWorkTable    locWHSWorkTable;
    WHSWorkLine     locWHSWorkLine;

    while select locWHSWorkTable
    where   locWHSWorkTable.WorkTransType   == WHSWorkTransType::Sales
        &&  locWHSWorkTable.WorkStatus      == WHSWorkStatus::Open
        &&  locWHSWorkTable.OrderNum        == this.SalesId
    {
        select sum(QtyWork)
        from    locWHSWorkLine
        where   locWHSWorkLine.WorkId       == locWHSWorkTable.WorkId
            &&  locWHSWorkLine.WorkStatus   == WHSWorkStatus::Open
            &&  locWHSWorkLine.ItemId       == this.ItemId
            &&  locWHSWorkLine.InventDimId  == this.InventDimId;

        retVal += locWHSWorkLine.QtyWork;
    }
    return retVal;
}

