[SysClientCacheDataMethodAttribute(true)]
display AVAPhysicalAvailForShipping avaPhysicalAvailForShipping()
{
    AVAPhysicalAvailForShipping locAVAPhysicalAvailForShipping;
    InventQtyAvailPhysical      locInventQtyAvailPhysical;

    locAVAPhysicalAvailForShipping  = this.avaPhysicalAvailAbilityForShipping();// - this.avaPhysicalReservedAbilityForShipping();
    locInventQtyAvailPhysical       = this.avaAvailPhysical();
