/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_salesLine">_salesLine</param>
/// <param name = "_inventDim">_inventDim</param>
/// <param name = "_resetPrice">_resetPrice</param>
/// <param name = "_uiEnabled">_uiEnabled</param>
public static void modifySalesQty(SalesLine    _salesLine,
                                  InventDim    _inventDim,
                                  boolean      _resetPrice,
                                  boolean      _uiEnabled)
{
    boolean resetPrice;
    boolean uiEnabled;

    resetPrice  = _resetPrice;
    uiEnabled   = _uiEnabled;

    resetPrice  = !AVASalesParameters::find().PriceSearch;
    uiEnabled   = true;

    next modifySalesQty(_salesLine,
                        _inventDim,
                        resetPrice,
                        uiEnabled);

    _salesLine.avaCheckActiveAltItemId();
    _salesLine.avaCheckPreferredUnit();
}

/// <summary>
/// AVA_011033
/// </summary>
public void avaCheckPreferredUnit()
{
    UnitOfMeasureConversion     conversion;
    Qty qtyPreferredUnit, roundedQtyPreferredUnit, convPreferredQty;
    UnitOfMeasureSymbol preferredUnit, transUnit;
    EcoResReleasedProductUnitConverter	unitConverter = EcoResReleasedProductUnitConverter::construct();

    if (AVASalesParameters::find().PreferredQtyForCentralWH && this.salesTable().KCS_CentralWarehouse)
    {
        transUnit = this.SalesUnit;

        select firstonly conversion where conversion.Product == this.inventTable().Product
        && conversion.ToUnitOfMeasure == UnitOfMeasure::findBySymbol(transUnit).RecId
        && conversion.NDXisDeliveryUnitPreferred;
        if (conversion.RecId)
        {
            preferredUnit = UnitOfMeasure::find(conversion.FromUnitOfMeasure).Symbol;
            qtyPreferredUnit    = this.SalesQty;
            qtyPreferredUnit =  unitConverter.convertGivenUnitSymbols(qtyPreferredUnit,
                                                 transUnit,
                                                 preferredUnit,
                                                 NoYes::Yes,
                                                 this.ItemId,
                                                 this.InventDimId,
                                                 NoYes::No);
            roundedQtyPreferredUnit = roundUp(qtyPreferredUnit, 1);
            convPreferredQty = unitConverter.convertGivenUnitSymbols(roundedQtyPreferredUnit,
                                                 preferredUnit,
                                                 transUnit,
                                                 NoYes::Yes,
                                                 this.ItemId,
                                                 this.InventDimId,
                                                 NoYes::No);
            if (qtyPreferredUnit != roundedQtyPreferredUnit)
            {
                warning(strFmt("@NDX:NXAPreferredUnitQty", convPreferredQty, this.LineNum, this.ItemId));
            }
        }
    }
}

/// <summary>
/// AVA_011033
/// </summary>
public void avaCheckActiveAltItemId()
{
    InventTable inventTable = this.inventTable();

    if (this.ItemId != inventTable.AltItemId)
    {
        if (inventTable.AltItemId && inventTable.UseAltItemId == ItemNumAlternative::Never)
        {
            warning(strFmt("@NDX:NXAAltItemExists", this.ItemId, inventTable.AltItemId));
        }
    }
}

/// <summary>
///    AVA <c>mustRecalcDiscOnSalesTypeChanged</c> method.
/// </summary>
/// <param name="_salesLineOrig">
///    <c>SalesLine</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
protected boolean mustRecalcDiscOnSalesTypeChanged(SalesLine _salesLineOrig)
{
    boolean ret;

    ret = next   mustRecalcDiscOnSalesTypeChanged(_salesLineOrig);
    ret = !AVASalesParameters::find().PriceSearch;

    return       ret;
}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "_custQuotationTrans">CustQuotationTrans</param>
/// <param name = "_copyPrecisely">boolean</param>
/// <param name = "_copyPriceDisc">boolean</param>
/// <param name = "_copyQty">boolean</param>
/// <param name = "_qty">Qty</param>
public void  initFromCustQuotationTrans(CustQuotationTrans  _custQuotationTrans,
                                        boolean             _copyPrecisely,
                                        boolean             _copyPriceDisc,
                                        boolean             _copyQty,
                                        Qty                 _qty                )
{
    CustQuotationJour   locCustQuotationJour;
    SalesQuotationTable locSalesQuotationTable;
    UnitOfMeasure       locUnitOfMeasure;


    locCustQuotationJour    = _custQuotationTrans.custQuotationJour();
    locSalesQuotationTable  = locCustQuotationJour.salesQuotationTable();

    next initFromCustQuotationTrans(_custQuotationTrans, 
                                    _copyPrecisely, 
                                    _copyPriceDisc, 
                                    _copyQty, 
                                    _qty                );

    locUnitOfMeasure = UnitOfMeasure::find(UnitOfMeasure::unitOfMeasureIdBySymbol(_custQuotationTrans.SalesUnit));
    if(     locUnitOfMeasure.RecId
            &&  locUnitOfMeasure.DecimalPrecision   == 0
            &&  locUnitOfMeasure.UnitOfMeasureClass == UnitOfMeasureClass::Quantity)
    {
        // InventMovement::setMinMaxQty(this, false, false, false, false);  // not working as expected, defaulting to minimum quantity of item with autocorrection 
        this.SalesQty = roundUp(this.SalesQty, 1);
    }                               
    else
    {
        InventMovement::setMinMaxMultipleQty(this, false);
    }
    this.QtyOrdered     = this.calcQtyOrdered(this.SalesQty);
    this.AVAQuotationId = locCustQuotationJour.KCS_QuotationId;
    this.AVApriceCalculation();
    this.LineAmount     = this.calcLineAmountForced();

    if(locSalesQuotationTable.QuotationExpiryDate < DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))
    {
        //this.AVAOrigQuotExpiredDate = locSalesQuotationTable.QuotationExpireDate; // no field, display QuotationExpiryDate AVAOrigQuotExpiredDate() on salesLine
        this.AVAQuotAGError = NoYes::Yes;
    }
    this.NDX_PAInfo = _custQuotationTrans.AVAPAInfo;
}

/// <summary>
/// AVA/WEN/2024/10/23   AVA_012570_PAInfo
/// </summary>
/// <param name = "_salesQuotationLine">SalesQuotationLine</param>
public void initFromSalesQuotationLine(SalesQuotationLine      _salesQuotationLine)
{
    next initFromSalesQuotationLine(_salesQuotationLine);
    this.NDX_PAInfo = _salesQuotationLine.AVAPAInfo;
}

/// <summary>
///    AVA <c>avaReserveSalesLine</c> method.
/// </summary>
/// <param name="_salesLine">
///    <c>SalesLine</c> as type
/// </param>
/// <param name="_qtyToReserve">
///    <c>InventQty</c> as type
/// </param>
/// <param name="_unreserve">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean avaReserveSalesLine( SalesLine   _salesLine      = this, 
                                    InventQty   _qtyToReserve   = 0, 
                                    boolean     _unreserve      = false )
{
    boolean                         retVal;

    InventTransIdSumSingleStatus    locInventTransIdSumSingleStatus;
    SalesLine                       locSalesLine;
    InventMovement                  locInventMovement;
    InventDim                       locInventDim;
    InventDimParm                   locInventDimParmCriteria;
    InventQtyReservPhysical         locOldReservedQty;
    InventQtyReservPhysical         locNewReservedQty;
    InventUpd_Reservation           locInventUpd_Reservation;
    InventQty                       locInventQtyToReserve;

    // Inline method to get current reserved quantity for specific inventDim
    InventQtyReservPhysical getReservedQty()
    {
        locInventDimParmCriteria.initFromInventDim(locInventDim);

        locInventTransIdSumSingleStatus = InventTransIdSumSingleStatus::newTransOriginIdStatus( InventTransOriginSalesLine::findInventTransOriginId(locSalesLine.DataAreaId, locSalesLine.InventTransId),
                                                                                                StatusReceipt::None,
                                                                                                StatusIssue::ReservPhysical);
        locInventTransIdSumSingleStatus.parmInventDimCriteria(locInventDim);
        locInventTransIdSumSingleStatus.parmInventDimParmCriteria(locInventDimParmCriteria);

        return locInventTransIdSumSingleStatus.reservPhysical();
    }

    retVal              = true;

    // Sales order line
    locSalesLine        = _salesLine;
    locInventMovement   = InventTrans::findTransId(locSalesLine.InventTransId).inventMovement(true);

    // Build inventDim-Record, where the quantity should be reserved
    locInventDim.clear();
    locInventDim = InventDim::findOrCreate(locSalesLine.inventDim());

    // Get current physical reserved Quantity
    locOldReservedQty           = getReservedQty();

    // Set quanity which should be reserved (negative values to reserve, postive value to unreserve)
    if(_qtyToReserve)
    {
        locInventQtyToReserve   = -_qtyToReserve;
    }
    else
    {
        locInventQtyToReserve   = _salesLine.reserveQty();
    }

    if(_unreserve)
    {
        locInventQtyToReserve = locInventQtyToReserve * (-1);
    }

    locInventUpd_Reservation    = InventUpd_Reservation::newInventDim(  locInventMovement,
                                                                        locInventDim,
                                                                        locInventQtyToReserve,
                                                                        true                    );
    locInventUpd_Reservation.updateNow();

    // Get new reserved quantity
    locNewReservedQty = getReservedQty();

    // Compare old and new reserved quantity to identify if reservation failed
  /*  if(     locOldReservedQty   == locNewReservedQty
        &&  _qtyToReserve       > 0)
    {
        error("@NDX:NXAReservationFailed");
        retVal = false;
    } */

    return retVal;
}

/// <summary>
///    AVA <c>avaGetReservableQty</c> method.
/// </summary>
/// <param name="_salesLine">
///    <c>SalesLine</c> as type
/// </param>
/// <param name="_reservedIncluding">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>SalesQty</c> as return value
/// </returns>
public SalesQty avaGetReservableQty(SalesLine _salesLine = this, boolean _reservedIncluding = true)
{
    SalesQty                retVal;

    SalesLine               locItemSetSalesLineParent;
    SalesLine               locItemSetSalesLineSearch;
    AVAStockAvailability    locAVAStockAvailability;
    AVAStockAvailability    locAVAStockAvailabilitySub;

    SalesQty                qtyPerItemSet;
    SalesQty                qtyItemSetsNeeded;
    SalesQty                qtyItemSetsAvailable;
    SalesQty                qtyItemSetsReserved;
    SalesQty                qtyItemSetsCovered;
    SalesQty                qtyItemSetsCoveredCurrent;
    SalesQty                qtyItemSetsCoveredTotal;

    InventTransId           weakestInventTransId;

    void calculateNeededItemSetQty()
    {
        boolean                 locHasShippingAbility;
        AVAShippingAbility      locShippingAbility;

        qtyPerItemSet               = locItemSetSalesLineSearch.SalesQty / minOne(locItemSetSalesLineParent.SalesQty);
        qtyItemSetsNeeded           = locItemSetSalesLineSearch.RemainSalesPhysical / minOne(qtyPerItemSet);

        locShippingAbility          = locItemSetSalesLineSearch.avaShippingAbility();
        locHasShippingAbility       = locShippingAbility == AVAShippingAbility::Control;

        if(locHasShippingAbility)
        {
            qtyItemSetsAvailable    = locItemSetSalesLineSearch.avaPhysicalAvailForShipping() / minOne(qtyPerItemSet);
            //qtyItemSetsReserved     = locItemSetSalesLineSearch.avaPhysicalReservedAbilityForShipping() / minOne(qtyPerItemSet);
            qtyItemSetsReserved     = locItemSetSalesLineSearch.reservedPhysicalInSalesUnit() / minOne(qtyPerItemSet);
        }
        else
        {
            qtyItemSetsAvailable    = locItemSetSalesLineSearch.avaAvailPhysical() / minOne(qtyPerItemSet);
            qtyItemSetsReserved     = locItemSetSalesLineSearch.reservedPhysicalInSalesUnit() / minOne(qtyPerItemSet);
        }
        qtyItemSetsCovered          = qtyItemSetsAvailable;
        if(_reservedIncluding)
        {
            qtyItemSetsCovered      += qtyItemSetsReserved;
        }
        qtyItemSetsCoveredCurrent   = qtyItemSetsCovered / minOne(qtyItemSetsNeeded);
        //qtyItemSetsCoveredCurrent   = locItemSetSalesLineSearch.avaAvailPhysical() / minOne(locItemSetSalesLineSearch.RemainSalesPhysical);
        if(qtyItemSetsCoveredCurrent > qtyItemSetsNeeded)
        {
            qtyItemSetsCoveredCurrent = qtyItemSetsNeeded;
        }
        else
        {
            qtyItemSetsCoveredCurrent = qtyItemSetsCovered;
        }
    }

    locAVAStockAvailability = this.avaGetStockAvailablity();

    if(locAVAStockAvailability == AVAStockAvailability::NotAvailable)
    {
        retVal = 0;
    }
    else if(locAVAStockAvailability == AVAStockAvailability::Available)
    {
        retVal = this.RemainSalesPhysical;
    }
    else if(locAVAStockAvailability == AVAStockAvailability::PartitialAvailable)
    {
        retVal = this.RemainSalesPhysical;

        if(     this.AVAItemSetComponent
            ||  (this.AVAItemSet && this.avaIsItemSetExpanded()) )
        {
            if(this.AVAItemSet)
            {
                locItemSetSalesLineParent = this;
            }
            if(this.AVAItemSetComponent && this.AVAItemSetParent)
            {
                locItemSetSalesLineParent = SalesLine::findInventTransId(this.AVAItemSetParent);
            }

            qtyItemSetsCoveredTotal = locItemSetSalesLineParent.RemainSalesPhysical;

            while select locItemSetSalesLineSearch
            where   locItemSetSalesLineSearch.SalesId           == locItemSetSalesLineParent.SalesId
                &&  locItemSetSalesLineSearch.AVAItemSetParent  == locItemSetSalesLineParent.InventTransId
            {
                locAVAStockAvailabilitySub = locItemSetSalesLineSearch.avaGetStockAvailablity();
                if(locAVAStockAvailabilitySub == AVAStockAvailability::Available)
                {
                    calculateNeededItemSetQty();
                }
                else if(locAVAStockAvailabilitySub == AVAStockAvailability::PartitialAvailable)
                {
                    calculateNeededItemSetQty();
                }

                if(qtyItemSetsCoveredCurrent < qtyItemSetsCoveredTotal)
                {
                    qtyItemSetsCoveredTotal = qtyItemSetsCoveredCurrent;
                    weakestInventTransId    = locItemSetSalesLineSearch.InventTransId;
                }
            }
            // calculate with weakest salesLine
            locItemSetSalesLineSearch = SalesLine::findInventTransId(weakestInventTransId);
            calculateNeededItemSetQty();

            retVal = qtyItemSetsCoveredCurrent;
        }
        else  // item set not exploded or standard sales line
        {
            retVal = this.avaAvailPhysical();
        }
    }
    return retVal;
}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "salesId">SalesId</param>
/// <param name = "_BundleRefId">InventTransId</param>
/// <returns>LineNum</returns>
public static LineNum  AVAnewLineNumAfterBundle(SalesId salesId, InventTransId _BundleRefId)
{
    LineNum         lastBundleLineNum;
    salesLine       localSalesLine;

    lastBundleLineNum    = Salesline::AVAlastBundleLineNum(salesId, _BundleRefId);

    if (lastBundleLineNum == SalesLine::lastLineNum(salesId))
    {
        return  lastBundleLineNum + 1;
    }
    else
    {
        localSalesLine   = SalesLine::find(salesId,lastBundleLineNum);
        return (localSalesLine.nextLineNum() - lastBundleLineNum) / 2 + lastBundleLineNum;
    }
}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "salesId">SalesId</param>
/// <param name = "_BundleRefId">InventTransId</param>
/// <returns>LineNum</returns>
public static LineNum  AVAlastBundleLineNum(SalesId salesId, InventTransId _BundleRefId)
{
    return (select maxof(LineNum) from salesLine
                        where salesLine.SalesId == salesId 
                           && salesLine.AVAItemSetParent == _BundleRefId).LineNum;
}

