/// <summary>
///    AVA <c>avaUpdateSalesTableKCS_PickingReleaseIndicator</c> method.
/// </summary>
public void avaUpdateSalesTableKCS_PickingReleaseIndicator()
{
    SalesTable                  locSalesTable;
    KCS_PickingReleaseIndicator locKCS_PickingReleaseIndicator;
    KCS_PickingReleaseIndicator locKCS_PickingReleaseIndicatorCalc;

    locSalesTable =  this.salesTable();

    locKCS_PickingReleaseIndicator      = locSalesTable.KCS_PickingReleaseIndicator;

    locKCS_PickingReleaseIndicatorCalc  = locSalesTable.avaCalcKCS_PickingReleaseIndicator();

    if(locKCS_PickingReleaseIndicator != locKCS_PickingReleaseIndicatorCalc)
    {
        ttsbegin;
        locSalesTable.selectForUpdate(true);
        locSalesTable.KCS_PickingReleaseIndicator = locKCS_PickingReleaseIndicatorCalc;
        locSalesTable.avaUpdateKCS_SOCSalesOrderPickingReleasedBy();
        locSalesTable.update();
        ttsCommit;
    }
}

/// <summary>
///    AVA <c>avaRemainQtyNotReserved</c> method.
/// </summary>
/// <returns>
///    <c>InventQty</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display InventQty avaRemainInventQtyNotReserved()
{
    InventQty retVal;

    retVal = this.RemainInventPhysical - this.reservedPhysical();
    if(retVal < 0.0)
    {
        retVal = 0.0;
    }

    return retVal;
}

/// <summary>
///    AVA <c>avaRemainInventQtyReservable</c> method.
/// </summary>
/// <returns>
///    <c>InventQty</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display InventQty avaRemainInventQtyReservable()
{
    InventQty retVal;
    InventQty locInventQty;

    retVal = 0.0;

    if(this.RemainInventPhysical > 0.0)                 // inventQty remaining
    {
        retVal = this.avaRemainInventQtyNotReserved();

        if(retVal > 0.0)                                // inventQty remaining not reserved
        {
            locInventQty = this.avaGetReservableQty();
            if(locInventQty > 0.0)                      // inventQty to reserve exist
            {
                if(retVal > locInventQty)
                {
                    retVal = locInventQty;
                }
            }
        }
    }
    return retVal;
}

