/// <summary>
/// designed from AVA 
/// </summary>
/// <param name = "_errorCorrectionMethods">_errorCorrectionMethods</param>
/// <returns>InventMovementQuantityErrorCorrectionMethods</returns>
public InventMovementQuantityErrorCorrectionMethods parmQuantityErrorCorrectionMethods(InventMovementQuantityErrorCorrectionMethods _errorCorrectionMethods)
{
    InventMovementQuantityErrorCorrectionMethods    locInventMovementQuantityErrorCorrectionMethods;

    if(_errorCorrectionMethods == null)
    {
        if(this.QuantityErrorCorrectionMethods)
        {
            locInventMovementQuantityErrorCorrectionMethods = InventMovementQuantityErrorCorrectionMethods::newFromPacked(this.QuantityErrorCorrectionMethods);
        }
        if(locInventMovementQuantityErrorCorrectionMethods == null)
        {
            locInventMovementQuantityErrorCorrectionMethods = InventMovementQuantityErrorCorrectionMethods::newStandard();
        }
    }
    else
    {
        locInventMovementQuantityErrorCorrectionMethods = _errorCorrectionMethods;
    }

    locInventMovementQuantityErrorCorrectionMethods = next parmQuantityErrorCorrectionMethods(locInventMovementQuantityErrorCorrectionMethods);

    if (this.salesQty == 0)
    {
        locInventMovementQuantityErrorCorrectionMethods.setAllErrorCorrectionMethods(InventMovementQuantityErrorCorrectionMethod::AcceptUserInput);
    }

    return locInventMovementQuantityErrorCorrectionMethods;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_salesTable">_salesTable</param>
/// <returns>boolean</returns>
public container AVAcheckOrigQuotation(SalesTable _salesTable = null)
{
    SalesQuotationTable     salesQuotationTable;
    SalesQuotationLine      salesQuotationLine;
    boolean     hasLineError = false;
    boolean     hasLineWarnung = false;
    SalesTable  locSalesTable;
    boolean   isReturnItem = this.returnItem();

    this.AVAQuotANError  = false;
    this.AVAQuotAAError  = false;
    this.AVAQuotAGError  = false;
    this.AVAQuotAAEError = false;

    locSalesTable = _salesTable ? _salesTable : this.salesTable();

    select firstonly QuotationId, CustAccount, QuotationExpiryDate, AVANoExpiryOverrun from salesQuotationTable
            where salesQuotationTable.QuotationId == this.AVAOrigQuotationId;

    this.AVAQuotANError = !salesQuotationTable.QuotationId ? NoYes::Yes : NoYes::No;

    if (!this.AVAQuotANError)
    {

        this.AVAQuotAAEError = (!isReturnItem && salesQuotationTable.QuotationId &&  salesQuotationTable.CustAccount != locSalesTable.CustAccount) ? NoYes::Yes : NoYes::No;

        select firstonly ItemId, RecId  from salesQuotationLine
        where salesQuotationLine.QuotationId == this.AVAOrigQuotationId
           && salesQuotationLine.ItemId      == this.ItemId;

        this.AVAQuotAAError = (salesQuotationTable.QuotationId && !salesQuotationLine.RecId) ? NoYes::Yes : NoYes::No;

        if (!this.AVAQuotAAError)
        {
            AVASalesParameters          salesParameters = AVASalesParameters::find();

            TransDate                   checkBasicDate = locSalesTable.KCS_PurchRefDate != dateNull() ? locSalesTable.KCS_PurchRefDate  :  DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());

            SalesQuotationNumOfDays     expNumOfDays = !salesQuotationTable.AVANoExpiryOverrun  ? salesParameters.SalesQuotationNumOfDays : 0;

            this.AVAQuotAGError = !isReturnItem && salesQuotationTable.QuotationId &&  salesQuotationTable.QuotationExpiryDate < checkBasicDate - expNumOfDays;

        }
    }

    if (this.AVAQuotANError || this.AVAQuotAAError || this.AVAQuotAGError)
    {
        hasLineError = true;
    }

    if (this.AVAQuotAAEError)
    {
        hasLineWarnung = true;
    }
    return [hasLineError,hasLineWarnung];
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>QuotationExpiryDate</returns>
[SysClientCacheDataMethodAttribute(true)]
display QuotationExpiryDate AVAOrigQuotExpiredDate()
{
    ExpirationDate      origQuotExpiredDate = SalesQuotationTable::find(this.AVAOrigQuotationId).QuotationExpiryDate;

    //return (this.AVAQuotationId == '' && this.AVAOrigQuotationId != '' && !this.AVAQuotANError && !this.AVAQuotAAError) ? SalesQuotationTable::find(this.AVAOrigQuotationId).QuotationExpiryDate : dateNull();
    return (this.AVAOrigQuotationId != ''  && origQuotExpiredDate <  DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())) ? origQuotExpiredDate : dateNull();
}

/// <summary>
/// designedfromAVA
/// </summary>
/// <returns>Name</returns>
[SysClientCacheDataMethodAttribute(true)]
display Name AVAOrigQuotationName()
{
    Name        custBusRelName, custRelNameOrig;

    if (this.AVAQuotationId)
    {
        SalesQuotationTable         salesQuotationTable = SalesQuotationTable::find(this.AVAQuotationId);
        custBusRelName  = salesQuotationTable.CustAccount ? salesQuotationTable.customerName() : salesQuotationTable.smmBusRelTable().name();
    }
    if (this.AVAOrigQuotationId)
    {
        SalesQuotationTable         salesQuotationTableOrig = SalesQuotationTable::find(this.AVAOrigQuotationId);
        custRelNameOrig  = salesQuotationTableOrig.CustAccount ? salesQuotationTableOrig.customerName() : salesQuotationTableOrig.smmBusRelTable().name();
    }
    return this.AVAQuotAAEError == NoYes::Yes ? 
           (this.AVAQuotationId != '' ? custBusRelName : (this.AVAOrigQuotationId != '' ? custRelNameOrig : '')) :
            '';
}

/// <summary>
/// AVA <c>avaItemSetSalesLineSetKCS_SOCPickingReleaseIndicator</c> method.
/// </summary>
/// <param name = "_includingSiblingComponents">boolean</param>
public void avaItemSetSalesLineSetKCS_SOCPickingReleaseIndicator(boolean _includingSiblingComponents = false)
{
    SalesLine  locSalesLine;

    ttsbegin;

    if(this.AVAItemSetComponent)
    {
        if(_includingSiblingComponents)
        {
            while select locSalesLine
            where   locSalesLine.InventTransId      != this.InventTransId
                &&  locSalesLine.AVAItemSetParent   == this.AVAItemSetParent
            {
                if(locSalesLine.RecId && locSalesLine.KCS_SOCPickingReleaseIndicator != this.KCS_SOCPickingReleaseIndicator)
                {
                    locSalesLine.selectForUpdate(true);
                    locSalesLine.KCS_SOCPickingReleaseIndicator = this.KCS_SOCPickingReleaseIndicator;
                    locSalesLine.update();
                }
            }
        }

        select firstonly locSalesLine
        where   locSalesLine.AVAItemSet
            &&  locSalesLine.InventTransId == this.AVAItemSetParent;

        if(locSalesLine.RecId && locSalesLine.KCS_SOCPickingReleaseIndicator != this.KCS_SOCPickingReleaseIndicator)
        {
            locSalesLine.selectForUpdate(true);
            locSalesLine.KCS_SOCPickingReleaseIndicator = this.KCS_SOCPickingReleaseIndicator;
            locSalesLine.update();
        }
    }

    ttsCommit;
}

/// <summary>
///    AVA <c>modifiedField</c> method.
/// </summary>
/// <param name="_fieldId">
///    <c>FieldId</c> as type
/// </param>
public void modifiedField(FieldId _fieldId)
{
    SalesLine   locSalesLineOrig;

    locSalesLineOrig = this.orig();

    next modifiedField(_fieldId);

    switch(_fieldId)
    {
        case fieldNum(SalesLine, AVADispoDate):
            this.AVADispoDateModifiedDateTime       = DateTimeUtil::utcNow();
            this.AVADispoDateModifiedById           = curUserId();
            this.setCalculatedShippingDate();
            break;

        case fieldNum(SalesLine, AVAProdSchedDate):
            this.AVAProdSchedDateModifiedDateTime   = DateTimeUtil::utcNow();
            this.AVAProdSchedDateModifiedById       = curUserId();
            this.setCalculatedShippingDate();
            break;

        case fieldNum(SalesLine,AVAShippingDateRequested) :
            this.setCalculatedShippingDate();
            break;

        case fieldNum(SalesLine, KCS_BOSCommissCutPct) :
            this.avaItemSetSetCommissionCutPctToComponents();
            break;

        default:
            break;
    }
}

