/// <summary>
///    AVA <c>copyCommissSplitFromQuotation</c> method.
/// </summary>
/// <param name="_quotationId">
///    <c>QuotationId</c> as type
/// </param>
public void copyCommissSplitFromQuotation(QuotationId _quotationId)
{
    KCS_BOSSalesQuotatCommissSplit      quotatSplit;
    KCS_BOSSalesOrderCommissSplit       salesOrderSplit;
    RecordInsertList                    recordInsertListQuotatSplit;

    delete_from salesOrderSplit
    where salesOrderSplit.SalesId           == this.SalesId
        && salesOrderSplit.InventTransId    == this.InventTransId
        && salesOrderSplit.RecipientBasic   == AVACBSRecipientBasic::Line;

    recordInsertListQuotatSplit = new RecordInsertList(tableNum(KCS_BOSSalesOrderCommissSplit));

    while select RecipientID, CommissSplit, SalesGroup, QuotationId from quotatSplit
    where   quotatSplit.QuotationId     == _quotationId
        &&  quotatSplit.RecipientBasic  == AVACBSRecipientBasic::Order
    {
        salesOrderSplit.SalesId          = this.SalesId;
        salesOrderSplit.InventTransId    = this.InventTransId;
        salesOrderSplit.RecipientBasic   = AVACBSRecipientBasic::Line;
        salesOrderSplit.RecipientID      = quotatSplit.RecipientID;
        salesOrderSplit.CommissSplit     = quotatSplit.CommissSplit;
        salesOrderSplit.SalesGroup       = quotatSplit.SalesGroup;

        recordInsertListQuotatSplit.add(salesOrderSplit);
    }

    recordInsertListQuotatSplit.insertDatabase();
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>SalesShippingDateRequested</returns>
public SalesShippingDateRequested   getCalculatedShippingDate()
{
    SalesShippingDateRequested       calcShipDate;
    SalesShippingDateRequested       calcShipDateTmp;

    if (this.AVAProdSchedDate != dateNull())
    {
        calcShipDate = this.AVAProdSchedDate;
    }
    else if (this.AVADispoDate != dateNull())
    {
        calcShipDate = this.AVADispoDate;
    }
    else if (this.AVAShippingDateRequested != dateNull())
    {
        calcShipDate = this.AVAShippingDateRequested;
    }

    calcShipDateTmp = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    if (calcShipDate < calcShipDateTmp) //BP: today())
    {
        calcShipDate = calcShipDateTmp;
    }

    return calcShipDate;
}

/// <summary>
/// desigbed from AVA
/// </summary>
public void setCalculatedShippingDate()
{
    this.ShippingDateRequested = this.getCalculatedShippingDate();
}

/// <summary>
/// designed from AVA
/// </summary>
public void initShippingDateFromSalesTable()
{
    SalesTable      locSalesTable = this.salesTable();
    this.AVAShippingDateRequested = locSalesTable.ShippingDateRequested;
    this.AVADispoDate             = locSalesTable.AVADispoDate;
    this.setCalculatedShippingDate();
}

/// <summary>
///    AVA <c>avaItemSetReserveSalesLine</c> method.
/// </summary>
/// <param name="_salesLine">
///    <c>SalesLine</c> as type
/// </param>
/// <param name="_qtyToReserve">
///    <c>InventQty</c> as type
/// </param>
/// <param name="_unreserve">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean avaItemSetReserveSalesLine(  SalesLine   _salesLine      = this,
                                            InventQty   _qtyToReserve   = 0,
                                            boolean     _unreserve      = false )
{
    boolean     retVal;

    SalesLine   locSalesLine;
    InventQty   locQtyToReserve;
    boolean     locUnreserve;

    SalesLine   locSalesLineSearch;
    SalesQty    locQtyToReserveTmp;

    retVal          = true;
    locSalesLine    = _salesLine;
    locQtyToReserve = _qtyToReserve;
    locUnreserve    = _unreserve;


    if(     locSalesLine.RecId
        &&  locQtyToReserve     )
    {
        if(locSalesLine.AVAItemSetExpanded)
        {
            while select locSalesLineSearch
            where   locSalesLineSearch.SalesId          == locSalesLine.SalesId
                &&  locSalesLineSearch.AVAItemSetParent == locSalesLine.InventTransId
            {
                locQtyToReserveTmp = locQtyToReserve * locSalesLineSearch.AVAItemSetCompQtyPerSerie / minOne(locSalesLineSearch.AVAItemSetSerie);

                this.avaReserveSalesLine(   locSalesLineSearch,
                                            locQtyToReserveTmp,
                                            locUnreserve        );
            }
        }
        else if(locSalesLine.AVAItemSetComponent)
        {
            locSalesLineSearch = locSalesLine.avaItemSetSalesLine();

            locQtyToReserveTmp = locQtyToReserve * locSalesLine.AVAItemSetSerie / minOne(locSalesLine.AVAItemSetCompQtyPerSerie);

            this.avaItemSetReserveSalesLine(locSalesLineSearch,
                                            locQtyToReserveTmp,
                                            locUnreserve        );
        }
        else
        {
            this.avaReserveSalesLine(   locSalesLine,
                                        locQtyToReserve,
                                        locUnreserve    );
        }
    }

    return retVal;
}

/// <summary>
///    AVA <c>avaConvertQtyFromUnitToUnit</c> method.
/// </summary>
/// <param name="_qty">
///    <c>Qty</c> as type
/// </param>
/// <param name="_fromUnitId">
///    <c>UnitIDBase</c> as type
/// </param>
/// <param name="_toUnitId">
///    <c>UnitIDBase</c> as type
/// </param>
/// <param name="_saleLine">
///    <c>SalesLine</c> as type
/// </param>
/// <returns>
///    <c>Qty</c> as return value
///    Without parameters returns the invent quantity of the sales line
/// </returns>
public Qty avaConvertQtyFromUnitToUnit( Qty         _qty        = this.SalesQty,
                                        UnitIDBase  _fromUnitId = this.SalesUnit,
                                        UnitIDBase  _toUnitId   = this.inventTable().inventUnitid(),
                                        SalesLine   _saleLine   = this                                  )
{
    Qty                                 retVal;

    EcoResReleasedProductUnitConverter  releasedProductUnitConverter;

    retVal              = _qty;

    if(_qty == 0.0)
    {
        retVal          = 0.0;
    }
    else if(_fromUnitId == _toUnitId)
    {
        retVal          = _qty;
    }
    else
    {
        if(_qty)
        {
            releasedProductUnitConverter = EcoResReleasedProductUnitConverter::construct();
            if (releasedProductUnitConverter.canBeConverted(UnitOfMeasure::unitOfMeasureIdBySymbol(_fromUnitId),
                                                            UnitOfMeasure::unitOfMeasureIdBySymbol(_toUnitId),
                                                            _saleLine.ItemId,
                                                            _saleLine.InventDimId                               )   )
            {
                retVal  = releasedProductUnitConverter.convert( _qty,
                                                                UnitOfMeasure::unitOfMeasureIdBySymbol(_fromUnitId),
                                                                UnitOfMeasure::unitOfMeasureIdBySymbol(_toUnitId),
                                                                NoYes::No,
                                                                _saleLine.ItemId,
                                                                _saleLine.InventDimId,
                                                                NoYes::Yes                                          );
            }
        }
    }
    return retVal;
}

