/// <summary>
/// throws a warning if current SalesLine needs and has a PA Info, error for header check
/// </summary>
/// <param name = "_isHeaderCheck">boolean</param>
public void avaValidatePAInfo(boolean _isHeaderCheck = false)
{
    if(this.NDX_PAInfo == ''
        && this.inventTable().AVAPAInfo
        && !_isHeaderCheck)
    {
        warning(strFmt("@NDX:NXAPAInfoCheckFailed", this.ItemId, this.LineNum));
    }
    else if(this.NDX_PAInfo == ''
        && this.inventTable().AVAPAInfo
        && _isHeaderCheck)
    {
        throw error(strFmt("@NDX:NXAPAInfoCheckFailed", this.ItemId, this.LineNum));
    }
}

