/// <summary>
/// AVA_011033
/// </summary>
/// <param name = "_inventDim">InventDim</param>
/// <param name = "_newlyCreatedSalesLine">SalesLine</param>
/// <returns>boolean</returns>
public boolean createAlternativeItem(InventDim _inventDim, SalesLine _newlyCreatedSalesLine)
{
    InventTable inventTable = inventTable::find(this.ItemId);
    //InventSum   inventsum = InventSum::find(this.ItemId, _inventDim.inventDimId);
    InventSum   inventsum;
    //if (!inventsum.AvailPhysical)
    //{
    select sum(AvailPhysical) from inventsum where inventsum.ItemId == this.ItemId
                                    && inventsum.InventSiteId == _inventDim.InventSiteId
                                    && inventsum.inventLocationId == _inventDim.InventLocationId;
    //}
    Qty availPhys = inventsum.AvailPhysical;

    if (inventTable.AltItemId && inventTable.UseAltItemId == ItemNumAlternative::Never && availPhys < this.SalesQty)
    {
        warning(strFmt("@NDX:NXAWarningSetAltItem", this.ItemId, availPhys, this.SalesQty));
    }
    boolean ret = next createAlternativeItem(_inventDim, _newlyCreatedSalesLine);


    return ret;
}

/// <summary>
///    AVA <c>avaItemSetSetCommissionCutPctToComponents</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean avaItemSetSetCommissionCutPctToComponents()
{
    boolean     retVal;

    SalesLine   locSalesLine;
    SalesLine   locSalesLineSearch;

    locSalesLine    = this;

    if(     locSalesLine.RecId
        &&  locSalesLine.AVAItemSet )
    {
        if(locSalesLine.AVAItemSetExpanded)
        {
            ttsbegin;
            while select locSalesLineSearch
            where   locSalesLineSearch.SalesId          == locSalesLine.SalesId
                &&  locSalesLineSearch.AVAItemSetParent == locSalesLine.InventTransId
            {
                locSalesLineSearch.selectForUpdate(true);
                locSalesLineSearch.KCS_BOSCommissCutPct = locSalesLine.KCS_BOSCommissCutPct;
                locSalesLineSearch.update();
                retVal = true;
            }
            ttscommit;
        }
    }
    return retVal;
}

