/// <summary>
/// NS Zelinka 21.02.24
/// Calculate line amount. Method considers Item is a set or component.
/// </summary>
/// <returns>calculated LineAmount</returns>
[SysClientCacheDataMethodAttribute(true)]
display LineAmount AVAdisplayLineAmount()
{
    LineAmount  amount;

    if (this.AVAItemSetComponent || this.SalesQty == 0)
    {
        amount = 0;
    }
    else
    {
        amount = (this.LineAmount / this.SalesQty) * this.RemainSalesPhysical;
    }

    return amount;
}

