///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean avaSetOrDoUpdateQuotationIdAfterImport(boolean _doUpdate = false)
{
    boolean retVal;
    boolean locValuesChanged;

    retVal = true;

    if(     this.AVAQuotationId     == '' 
        &&  this.AVAOrigQuotationId != '')
    {
        this.AVAQuotationId = this.AVAOrigQuotationId;
        locValuesChanged = true;
    }

    if(_doUpdate && locValuesChanged)
    {
        ttsbegin;
        this.selectForUpdate(_doUpdate);
        this.doUpdate();
        ttscommit;
    }

    return retVal;
}

