public void  update(boolean  _dropInvent,
                    Common   _childBuffer,
                    boolean  _updateOrderLineOfDeliverySchedule,
                    boolean  _mcrAutoallocate,
                    boolean  _cameFromCreate,
                    boolean  _promptSuppItem
                    )
{
    boolean     updateEstimate = false;

    if(this.SalesQty != this.orig().salesQty)
    {
        ProdTable avaProdTable = this.avaSalesLineHasProduction();

        if(avaProdTable.RecId)
        {
            this.SalesQty = this.orig().salesQty;
            throw error(strFmt("@NDX:NXAQtyChangeProdTableError", avaProdTable.ProdId, avaProdTable.ProdStatus));
        }
    }

    if (this.LineAmount != this.orig().lineAmount || this.SalesPrice != this.orig().salesPrice)
    {
        updateEstimate = true;
    }

    next update(_dropInvent, _childBuffer, _updateOrderLineOfDeliverySchedule, _mcrAutoallocate, _cameFromCreate, _promptSuppItem);

    if (updateEstimate)
    {
        this.avaUpdateSalesTableEstimate();
    }

}

void delete(Common childBuffer, boolean updateOrderLineOfDeliverySchedule)
{
    ProdTable avaProdTable = this.avaSalesLineHasProduction();

    if(avaProdTable.RecId)
    {
        throw error(strFmt("@NDX:NXAInventLineDeleteProdTableError", this.ItemId, avaProdTable.ProdId, avaProdTable.ProdStatus));
    }

    next delete(childBuffer, updateOrderLineOfDeliverySchedule);
}

/// <summary>
/// Checks if any associated SalesLine record is connected to a ProdTable record
/// </summary>
/// <returns>ProdTable</returns>
public ProdTable avaSalesLineHasProduction()
{
    InventTrans         avaInventTrans;
    InventTransOrigin   avaInventTransOrigin, avaInventTransOrigin_Prod;
    ProdTable           avaProdTable;

    select firstonly avaInventTrans
        join avaInventTransOrigin
        join avaInventTransOrigin_Prod
        join avaProdTable
        where avaInventTrans.InventTransOrigin          == avaInventTransOrigin.RecId
        && avaInventTrans.MarkingRefInventTransOrigin   == avaInventTransOrigin_Prod.RecId
        && avaProdTable.InventTransId                   == avaInventTransOrigin_Prod.InventTransId
        && (avaInventTransOrigin.InventTransId      == this.InventTransId
            || avaInventTransOrigin.InventTransId   == this.InventTransIdReturn);

    return avaProdTable;
}

