/// <summary>
/// N.Freidenberger  27.09.2024
/// </summary>
/// <param name = "_isReservedQtyPreCalc">boolean</param>
/// <param name = "_reservedQty">Qty</param>
/// <returns>Qty</returns>
public Qty AVAgetMinAvailToReserveQtyFromItemSetComponents(boolean  _isReservedQtyPreCalc = false, Qty          _reservedQty = 0)
{
    Qty         itemSetAvailToReservQty;
    Qty         itemSetreservedQty;
    Qty         componentAvailPhys;
    Qty         itemSetAvailPhys;
    SalesLine   componentSalesLine;
    boolean     firstComp = true;

    while select componentSalesLine
        where componentSalesLine.SalesId == this.SalesId
        && componentSalesLine.AVAItemSetComponent == NoYes::Yes
        && componentSalesLine.AVAItemSetParent    == this.InventTransId
    {
        if (firstComp)
        {
            if (_isReservedQtyPreCalc)
            {
                itemSetreservedQty = _reservedQty;
            }
            else
            {
                SalesQty locCompReservedQty        = componentSalesLine.reservedPhysicalInSalesUnit();
                itemSetreservedQty               = componentSalesLine.AVAItemSetCompQtyPerSerie != 0 ? locCompReservedQty * componentSalesLine.AVAItemSetSerie / componentSalesLine.AVAItemSetCompQtyPerSerie : locCompReservedQty * componentSalesLine.AVAItemSetSerie;
            }
            itemSetAvailToReservQty = componentSalesLine.AVAItemSetCompQtyPerSerie != 0 ? roundDown((componentSalesLine.RemainInventPhysical * componentSalesLine.AVAItemSetSerie / componentSalesLine.AVAItemSetCompQtyPerSerie),0) : componentSalesLine.RemainInventPhysical * componentSalesLine.AVAItemSetSerie;
            //itemSetAvailToReservQty -= itemSetreservedQty;
            firstComp = false;
        }
        componentAvailPhys = componentSalesLine.AVAAvailToReserveQty();
        itemSetAvailPhys   = componentSalesLine.AVAItemSetCompQtyPerSerie != 0 ? roundDown((componentAvailPhys * componentSalesLine.AVAItemSetSerie / componentSalesLine.AVAItemSetCompQtyPerSerie),0) : componentAvailPhys * componentSalesLine.AVAItemSetSerie;
        itemSetAvailToReservQty   =  itemSetAvailPhys < itemSetAvailToReservQty ? itemSetAvailPhys : itemSetAvailToReservQty;
    }
    return      itemSetAvailToReservQty;
    //return      itemSetAvailToReservQty - _reservedQty;
}

