/// <summary>
/// NDX Check if Color is set
/// </summary>
/// <param name = "_isHeaderCheck"></param>
public void ndxValidateColor(boolean _isHeaderCheck = false)
{
    InventDim lInventDim = InventDim::find(this.InventDimId);

    if(lInventDim && _isHeaderCheck && lInventDim.InventColorId == 'RAL 0000')
    {
        throw error(strfmt("@NDX:NDXColorCheckFailed", this.ItemId, this.LineNum));
    }
    else if(lInventDim && _isHeaderCheck && lInventDim.InventColorId == 'RAL 0000')
    {
        warning(strFmt("@NDX:NDXColorCheckFailed", this.ItemId, this.LineNum));
    }
}
